","service":"class LibraryManagementSystemSystem_AutoGenerated {
  /*Definition: librarian scans a user ID and a book barcode to process a borrowing request.
   *Precondition: The system first checks whether the user exists, is not suspended, and still has borrowing quota.
   *Postcondition:Then it confirms the selected copy is available (or reserved for this same user), creates a new loan record, sets the due date by user type, updates book status to loaned, and returns true when the checkout succeeds.*/
  borrowBook(uid: string, barcode: string): boolean {
    /*OCL Invocation Environment*/
    const oclInvocationTime = dayjs();
    /*Definition Start*/
    let user: User = evaluateDefinition(
      () =>
        l({
          logic: () =>
            getRepository(User).find(
              (candidate: User) =>
                l({
                  logic: () => StandardOPs.oclEquals(candidate.UserID, uid),
                  description: "candidate.UserID=uid",
                }).build().pass,
            ),
          description:
            "User.allInstances()->any(candidate:User|candidate.UserID=uid)",
        }).build().pass,
    );
    let copy: BookCopy = evaluateDefinition(
      () =>
        l({
          logic: () =>
            getRepository(BookCopy).find(
              (candidate: BookCopy) =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(candidate.Barcode, barcode),
                  description: "candidate.Barcode=barcode",
                }).build().pass,
            ),
          description:
            "BookCopy.allInstances()->any(candidate:BookCopy|candidate.Barcode=barcode)",
        }).build().pass,
    );
    let student: Student = evaluateDefinition(
      () =>
        l({
          logic: () =>
            getRepository(Student).find(
              (candidate: Student) =>
                l({
                  logic: () => StandardOPs.oclEquals(candidate.UserID, uid),
                  description: "candidate.UserID=uid",
                }).build().pass,
            ),
          description:
            "Student.allInstances()->any(candidate:Student|candidate.UserID=uid)",
        }).build().pass,
    );
    let faculty: Faculty = evaluateDefinition(
      () =>
        l({
          logic: () =>
            getRepository(Faculty).find(
              (candidate: Faculty) =>
                l({
                  logic: () => StandardOPs.oclEquals(candidate.UserID, uid),
                  description: "candidate.UserID=uid",
                }).build().pass,
            ),
          description:
            "Faculty.allInstances()->any(candidate:Faculty|candidate.UserID=uid)",
        }).build().pass,
    );
    let reservation: Reserve = evaluateDefinition(
      () =>
        l({
          logic: () =>
            getRepository(Reserve).find(
              (candidate: Reserve) =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(candidate.ReservedUser, user),
                  description: "candidate.ReservedUser=user",
                })
                  .and({
                    logic: () =>
                      StandardOPs.oclEquals(candidate.ReservedCopy, copy),
                    description: "candidate.ReservedCopy=copy",
                  })
                  .and({
                    logic: () =>
                      StandardOPs.oclEquals(candidate.IsReserveClosed, false),
                    description: "candidate.IsReserveClosed=false",
                  })
                  .build().pass,
            ),
          description:
            "Reserve.allInstances()->any(candidate:Reserve|candidate.ReservedUser=userandcandidate.ReservedCopy=copyandcandidate.IsReserveClosed=false)",
        }).build().pass,
    );
    let dueDate: dayjs.Dayjs = evaluateDefinition(
      () =>
        l()
          .if({
            logic: () =>
              l({
                logic: () => StandardOPs.oclIsTypeOf(user, Student),
                description: "user.oclIsTypeOf(Student)",
              }),
            description: "user.oclIsTypeOf(Student)",
            then: l({
              logic: () => dayjs(oclInvocationTime.startOf("day")).add(30, "d"),
              description: "Today.After(30)",
            }),
            else: l({
              logic: () => dayjs(oclInvocationTime.startOf("day")).add(60, "d"),
              description: "Today.After(60)",
            }),
          })
          .build().pass,
    );
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () =>
          getRepository(User).some(
            (candidate: User) =>
              l({
                logic: () => StandardOPs.oclEquals(candidate.UserID, uid),
                description: "candidate.UserID=uid",
              }).build().pass,
          ),
        description:
          "User.allInstances()->exists(candidate:User|candidate.UserID=uid)",
      })
        .and({
          logic: () =>
            getRepository(BookCopy).some(
              (candidate: BookCopy) =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(candidate.Barcode, barcode),
                  description: "candidate.Barcode=barcode",
                }).build().pass,
            ),
          description:
            "BookCopy.allInstances()->exists(candidate:BookCopy|candidate.Barcode=barcode)",
        })
        .and({
          logic: () =>
            StandardOPs.oclEquals(user.BorrowStatus, BorrowStatus.NORMAL),
          description: "user.BorrowStatus=BorrowStatus::NORMAL",
        })
        .and({
          logic: () => StandardOPs.oclEquals(user.SuspensionDays, 0),
          description: "user.SuspensionDays=0",
        })
        .and({
          logic: () =>
            l().if({
              logic: () =>
                l({
                  logic: () => StandardOPs.oclIsTypeOf(user, Student),
                  description: "user.oclIsTypeOf(Student)",
                }),
              description: "user.oclIsTypeOf(Student)",
              then: l().if({
                logic: () =>
                  l({
                    logic: () =>
                      StandardOPs.oclEquals(
                        student.Programme,
                        Programme.BACHELOR,
                      ),
                    description: "student.Programme=Programme::BACHELOR",
                  }),
                description: "student.Programme=Programme::BACHELOR",
                then: l({
                  logic: () => user.LoanedNumber < 20,
                  description: "user.LoanedNumber<20",
                }),
                else: l().if({
                  logic: () =>
                    l({
                      logic: () =>
                        StandardOPs.oclEquals(
                          student.Programme,
                          Programme.MASTER,
                        ),
                      description: "student.Programme=Programme::MASTER",
                    }),
                  description: "student.Programme=Programme::MASTER",
                  then: l({
                    logic: () => user.LoanedNumber < 40,
                    description: "user.LoanedNumber<40",
                  }),
                  else: l({
                    logic: () => user.LoanedNumber < 60,
                    description: "user.LoanedNumber<60",
                  }),
                }),
              }),
              else: l().if({
                logic: () =>
                  l({
                    logic: () => StandardOPs.oclIsTypeOf(user, Faculty),
                    description: "user.oclIsTypeOf(Faculty)",
                  }),
                description: "user.oclIsTypeOf(Faculty)",
                then: l({
                  logic: () => user.LoanedNumber < 60,
                  description: "user.LoanedNumber<60",
                }),
                else: l({
                  logic: () => false,
                  description: "false",
                }),
              }),
            }),
          description:
            "(ifuser.oclIsTypeOf(Student)thenifstudent.Programme=Programme::BACHELORthenuser.LoanedNumber<20elseifstudent.Programme=Programme::MASTERthenuser.LoanedNumber<40elseuser.LoanedNumber<60endifendifelseifuser.oclIsTypeOf(Faculty)thenuser.LoanedNumber<60elsefalseendifendif)",
        })
        .and({
          logic: () =>
            l({
              logic: () =>
                StandardOPs.oclEquals(copy.Status, CopyStatus.AVAILABLE),
              description: "copy.Status=CopyStatus::AVAILABLE",
            }).or({
              logic: () =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(copy.Status, CopyStatus.ONHOLDSHELF),
                  description: "copy.Status=CopyStatus::ONHOLDSHELF",
                })
                  .and({
                    logic: () => StandardOPs.oclEquals(copy.IsReserved, true),
                    description: "copy.IsReserved=true",
                  })
                  .and({
                    logic: () =>
                      getRepository(Reserve).some(
                        (candidate: Reserve) =>
                          l({
                            logic: () =>
                              StandardOPs.oclEquals(
                                candidate.ReservedUser,
                                user,
                              ),
                            description: "candidate.ReservedUser=user",
                          })
                            .and({
                              logic: () =>
                                StandardOPs.oclEquals(
                                  candidate.ReservedCopy,
                                  copy,
                                ),
                              description: "candidate.ReservedCopy=copy",
                            })
                            .and({
                              logic: () =>
                                StandardOPs.oclEquals(
                                  candidate.IsReserveClosed,
                                  false,
                                ),
                              description: "candidate.IsReserveClosed=false",
                            })
                            .build().pass,
                      ),
                    description:
                      "Reserve.allInstances()->exists(candidate:Reserve|candidate.ReservedUser=userandcandidate.ReservedCopy=copyandcandidate.IsReserveClosed=false)",
                  }),
              description:
                "(copy.Status=CopyStatus::ONHOLDSHELFandcopy.IsReserved=trueandReserve.allInstances()->exists(candidate:Reserve|candidate.ReservedUser=userandcandidate.ReservedCopy=copyandcandidate.IsReserveClosed=false))",
            }),
          description:
            "(copy.Status=CopyStatus::AVAILABLEor(copy.Status=CopyStatus::ONHOLDSHELFandcopy.IsReserved=trueandReserve.allInstances()->exists(candidate:Reserve|candidate.ReservedUser=userandcandidate.ReservedCopy=copyandcandidate.IsReserveClosed=false)))",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*OCL Pre-state Snapshot*/
    const oclState = new OCLStateSnapshot(map, [this]);
    /*OCL Effect Trace*/
    const oclExecutionTrace = new OCLExecutionTrace();
    const result = (() => {
      /*Postcondition Effects Start*/
      let loan: Loan;
      return l({
        execute: () => (loan = new Loan()),
        description: "loan.oclIsNew()",
      })
        .and({
          execute: () => StandardOPs.includeIfAbsent(getRepository(Loan), loan),
          description: "Loan.allInstances()->includes(loan)",
        })
        .and({
          execute: () => (loan.LoanedUser = user),
          description: "loan.LoanedUser=user",
        })
        .and({
          execute: () => (loan.LoanedCopy = copy),
          description: "loan.LoanedCopy=copy",
        })
        .and({
          execute: () => StandardOPs.includeIfAbsent(user.LoanedBook, loan),
          description: "user.LoanedBook->includes(loan)",
        })
        .and({
          execute: () => StandardOPs.includeIfAbsent(copy.LoanedRecord, loan),
          description: "copy.LoanedRecord->includes(loan)",
        })
        .and({
          execute: () => (loan.LoanDate = oclInvocationTime.startOf("day")),
          description: "loan.LoanDate=Today",
        })
        .and({
          execute: () => (loan.IsReturned = false),
          description: "loan.IsReturned=false",
        })
        .and({
          execute: () => (loan.DueDate = dueDate),
          description: "loan.DueDate=dueDate",
        })
        .and({
          execute: () =>
            (user.LoanedNumber = oclState.preValue(user, "LoanedNumber") + 1),
          description: "user.LoanedNumber=user.LoanedNumber@pre+1",
        })
        .and({
          execute: () => (copy.Status = CopyStatus.LOANED),
          description: "copy.Status=CopyStatus::LOANED",
        })
        .and({
          execute: () => (loan.OverDue3Days = false),
          description: "loan.OverDue3Days=false",
        })
        .and({
          execute: () => (loan.OverDue10Days = false),
          description: "loan.OverDue10Days=false",
        })
        .and({
          execute: () => (loan.OverDue17Days = false),
          description: "loan.OverDue17Days=false",
        })
        .and({
          execute: () => (loan.OverDue31Days = false),
          description: "loan.OverDue31Days=false",
        })
        .and({
          execute: () =>
            l().if({
              logic: () =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(
                      oclState.preValue(copy, "Status"),
                      CopyStatus.ONHOLDSHELF,
                    ),
                  description: "copy.Status@pre=CopyStatus::ONHOLDSHELF",
                }),
              description: "copy.Status@pre=CopyStatus::ONHOLDSHELF",
              then: l({
                execute: () => (copy.IsReserved = false),
                description: "copy.IsReserved=false",
              }).and({
                execute: () => (reservation.IsReserveClosed = true),
                description: "reservation.IsReserveClosed=true",
              }),
              else: l({
                execute: () =>
                  (copy.IsReserved = oclState.preValue(copy, "IsReserved")),
                description: "copy.IsReserved=copy.IsReserved@pre",
              }),
            }),
          description:
            "(ifcopy.Status@pre=CopyStatus::ONHOLDSHELFthencopy.IsReserved=falseandreservation.IsReserveClosed=trueelsecopy.IsReserved=copy.IsReserved@preendif)",
        })
        .and({
          execute: () => true,
          description: "result=true",
        })
        .build().value;
      /*Postcondition Effects End*/
    })();
    /*OCL Post-state Snapshot*/
    oclState.capturePost();
    const {
      errorMessage: postconditionErrorMessage,
      pass: isPostconditionPass,
    } = (() => {
      /*Postcondition Check Start*/
      let loan: Loan = oclState.findNew(Loan);
      return l({
        logic: () => oclState.isNew(loan, Loan),
        description: "loan.oclIsNew()",
      })
        .and({
          logic: () => StandardOPs.includes(getRepository(Loan), loan),
          description: "Loan.allInstances()->includes(loan)",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.LoanedUser, user),
          description: "loan.LoanedUser=user",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.LoanedCopy, copy),
          description: "loan.LoanedCopy=copy",
        })
        .and({
          logic: () => StandardOPs.includes(user.LoanedBook, loan),
          description: "user.LoanedBook->includes(loan)",
        })
        .and({
          logic: () => StandardOPs.includes(copy.LoanedRecord, loan),
          description: "copy.LoanedRecord->includes(loan)",
        })
        .and({
          logic: () =>
            StandardOPs.oclEquals(
              loan.LoanDate,
              oclInvocationTime.startOf("day"),
            ),
          description: "loan.LoanDate=Today",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.IsReturned, false),
          description: "loan.IsReturned=false",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.DueDate, dueDate),
          description: "loan.DueDate=dueDate",
        })
        .and({
          logic: () =>
            StandardOPs.oclEquals(
              user.LoanedNumber,
              oclState.preValue(user, "LoanedNumber") + 1,
            ),
          description: "user.LoanedNumber=user.LoanedNumber@pre+1",
        })
        .and({
          logic: () => StandardOPs.oclEquals(copy.Status, CopyStatus.LOANED),
          description: "copy.Status=CopyStatus::LOANED",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.OverDue3Days, false),
          description: "loan.OverDue3Days=false",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.OverDue10Days, false),
          description: "loan.OverDue10Days=false",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.OverDue17Days, false),
          description: "loan.OverDue17Days=false",
        })
        .and({
          logic: () => StandardOPs.oclEquals(loan.OverDue31Days, false),
          description: "loan.OverDue31Days=false",
        })
        .and({
          logic: () =>
            l().if({
              logic: () =>
                l({
                  logic: () =>
                    StandardOPs.oclEquals(
                      oclState.preValue(copy, "Status"),
                      CopyStatus.ONHOLDSHELF,
                    ),
                  description: "copy.Status@pre=CopyStatus::ONHOLDSHELF",
                }),
              description: "copy.Status@pre=CopyStatus::ONHOLDSHELF",
              then: l({
                logic: () => StandardOPs.oclEquals(copy.IsReserved, false),
                description: "copy.IsReserved=false",
              }).and({
                logic: () =>
                  StandardOPs.oclEquals(reservation.IsReserveClosed, true),
                description: "reservation.IsReserveClosed=true",
              }),
              else: l({
                logic: () =>
                  StandardOPs.oclEquals(
                    copy.IsReserved,
                    oclState.preValue(copy, "IsReserved"),
                  ),
                description: "copy.IsReserved=copy.IsReserved@pre",
              }),
            }),
          description:
            "(ifcopy.Status@pre=CopyStatus::ONHOLDSHELFthencopy.IsReserved=falseandreservation.IsReserveClosed=trueelsecopy.IsReserved=copy.IsReserved@preendif)",
        })
        .and({
          logic: () => StandardOPs.oclEquals(result, true),
          description: "result=true",
        })
        .build();
      /*Postcondition Check End*/
    })();
    if (!isPostconditionPass) {
      throw new PostconditionError(postconditionErrorMessage);
    }
    return result;
  }
}
","entry":"import dayjs from "dayjs";
import {evaluateDefinition, l, OCLExecutionTrace, OCLStateSnapshot, PostconditionError, PreconditionError, StandardOPs} from "../globalEntry";
/*The user account*/
class User {
  /*User ID*/
  UserID: string;
  /*Name*/
  Name: string;
  /*Sex*/
  Sex: Sex;
  /*Password*/
  Password: string;
  /*Email*/
  Email: string;
  /*Faculty*/
  Faculty: string;
  /*Number of loaned books*/
  LoanedNumber: number;
  /*Borrow status*/
  BorrowStatus: BorrowStatus;
  /*Suspension days*/
  SuspensionDays: number;
  /*Overdue fee*/
  OverDueFee: number;
  /*Loans made by the user*/
  LoanedBook: Loan[];
  /*Reservations made by the user*/
  ReservedBook: Reserve[];
  /*Books recommended by the user*/
  RecommendedBook: RecommendBook[];
}
/*The student account*/
class Student extends User {
  /*Major*/
  Major: string;
  /*Programme*/
  Programme: Programme;
  /*Registration status*/
  RegistrationStatus: Programme;
}
/*The faculty account*/
class Faculty extends User {
  /*Position*/
  Position: Position;
  /*Status*/
  Status: Status;
}
/*Books owned by the library*/
class Book {
  /*Call Number*/
  CallNo: string;
  /*Title*/
  Title: string;
  /*Edition*/
  Edition: string;
  /*Author*/
  Author: string;
  /*Publisher*/
  Publisher: string;
  /*Description*/
  Description: string;
  /*ISBN*/
  ISBn: string;
  /*Number of copies*/
  CopyNum: number;
  /*Copies of the book*/
  Copys: BookCopy[];
  /*Subjects of the book*/
  Subject: Subject[];
}
/*The subject of books*/
class Subject {
  /*Subject name*/
  Name: string;
  /*Super subject*/
  SuperSubject: Subject;
  /*Sub subjects*/
  SubSubject: Subject;
}
/*The copy of a book for borrowing*/
class BookCopy {
  /*Barcode*/
  Barcode: string;
  /*Status*/
  Status: CopyStatus;
  /*Location*/
  Location: string;
  /*Is reserved*/
  IsReserved: boolean;
  /*The book this copy belongs to*/
  BookBelongs: Book;
  /*Loan records of this copy*/
  LoanedRecord: Loan[];
  /*Reservation records of this copy*/
  ReservationRecord: Reserve[];
}
/*The record of borrowing books*/
class Loan {
  /*Loan date*/
  LoanDate: dayjs.Dayjs;
  /*Renew date*/
  RenewDate: dayjs.Dayjs;
  /*Due date*/
  DueDate: dayjs.Dayjs;
  /*Return date*/
  ReturnDate: dayjs.Dayjs;
  /*Number of times renewed*/
  RenewedTimes: number;
  /*Is returned*/
  IsReturned: boolean;
  /*Overdue fee*/
  OverDueFee: number;
  /*Overdue for 3 days*/
  OverDue3Days: boolean;
  /*Overdue for 10 days*/
  OverDue10Days: boolean;
  /*Overdue for 17 days*/
  OverDue17Days: boolean;
  /*Overdue for 31 days*/
  OverDue31Days: boolean;
  /*User who loaned the book*/
  LoanedUser: User;
  /*The copy loaned*/
  LoanedCopy: BookCopy;
  /*Librarian who processed the loan*/
  LoanLibrarian: Librarian;
  /*Librarian who processed the return*/
  ReturnLibrarian: Librarian;
}
/*The record of book reservation*/
class Reserve {
  /*Reservation date*/
  ReserveDate: dayjs.Dayjs;
  /*Is reservation closed*/
  IsReserveClosed: boolean;
  /*Reserved copy*/
  ReservedCopy: BookCopy;
  /*User who made the reservation*/
  ReservedUser: User;
}
/*The book recommended by users to the library*/
class RecommendBook extends Book {
  /*Recommendation date*/
  RecommendDate: dayjs.Dayjs;
  /*User who recommended the book*/
  RecommendUser: User;
}
/*The administrator account*/
class Administrator {
  /*Administrator ID*/
  AdminID: string;
  /*Username*/
  UserName: string;
  /*Password*/
  Password: string;
}
/*The librarian account*/
class Librarian {
  /*Librarian ID*/
  LibrarianID: string;
  /*Name*/
  Name: string;
  /*Password*/
  Password: string;
}
enum Sex {
  M = "M",
  F = "F",
}
enum BorrowStatus {
  NORMAL = "NORMAL",
  SUSPEND = "SUSPEND",
}
enum Programme {
  BACHELOR = "BACHELOR",
  MASTER = "MASTER",
  PHD = "PHD",
}
enum Position {
  ASSISTANTPROFESSORS = "ASSISTANTPROFESSORS",
  ASSOCIATEPROFESSOR = "ASSOCIATEPROFESSOR",
  PROFESSOR = "PROFESSOR",
  CHAIRPROFESSOR = "CHAIRPROFESSOR",
}
enum Status {
  HASRETIRED = "HASRETIRED",
  INPOSITION = "INPOSITION",
}
enum CopyStatus {
  AVAILABLE = "AVAILABLE",
  INPROCESSING = "INPROCESSING",
  LIBUSEONLY = "LIBUSEONLY",
  ONHOLDSHELF = "ONHOLDSHELF",
  LOANED = "LOANED",
}
const map = new Map();
map.set(User, []);
map.set(Student, []);
map.set(Faculty, []);
map.set(Book, []);
map.set(Subject, []);
map.set(BookCopy, []);
map.set(Loan, []);
map.set(Reserve, []);
map.set(RecommendBook, []);
map.set(Administrator, []);
map.set(Librarian, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export {
  Sex,
  BorrowStatus,
  Programme,
  Position,
  Status,
  CopyStatus,
  User,
  Student,
  Faculty,
  Book,
  Subject,
